//! Exact, locked Market Data evidence transport for the isolated R&D transaction.
//!
//! These functions only return stored evidence. Existing Rust Owner decoders and binders retain
//! authority to accept or reject every readback and to mint Strategy Input receipts.

pub(super) const SCHEMA_V1: &[&str] = &[
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_strategy_input_declarations_v1(p_pit BYTEA,p_design BYTEA) RETURNS TABLE(input_role_identity BYTEA,request_bytes BYTEA,request_meaning_digest BYTEA,owner_binding_digest BYTEA) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT d.input_role_identity,d.request_bytes,d.request_meaning_digest,d.owner_binding_digest FROM market_data_private.strategy_input_binding_declarations_v1 d WHERE d.pit_request_identity=p_pit AND d.strategy_design_identity=p_design AND session_user='rd_owner' ORDER BY d.input_role_identity LIMIT 65 FOR SHARE OF d $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_source_for_strategy_input_v1(p_binding BYTEA) RETURNS TABLE(row_identity BYTEA,fact_digest BYTEA,request_identity BYTEA,request_digest BYTEA,correction_stream_identity TEXT,correction_sequence BIGINT,fact_lineage_root BYTEA,fact_lineage_version BIGINT,aggregate_json JSONB,outbox_event_identity BYTEA,outbox_aggregate_identity BYTEA,outbox_payload BYTEA,outbox_digest BYTEA,head_lineage_root BYTEA,head_identity BYTEA,head_digest BYTEA,head_version BIGINT) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT f.binding_id,f.fact_digest,NULL::BYTEA,NULL::BYTEA,NULL::TEXT,NULL::BIGINT,f.lineage_root,f.lineage_version,f.aggregate_json,o.event_identity,o.aggregate_identity,o.payload,o.payload_digest,h.lineage_root,h.binding_id,h.fact_digest,h.lineage_version FROM market_data_private.source_binding_facts_v1 f JOIN market_data_private.source_binding_outbox_v1 o ON o.aggregate_identity=f.binding_id JOIN market_data_private.source_binding_heads_v1 h ON h.lineage_root=f.lineage_root WHERE f.binding_id=p_binding AND session_user='rd_owner' FOR SHARE OF f,o,h $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_pit_observation_batch_for_strategy_input_v1(p_snapshot BYTEA) RETURNS TABLE(source_binding_identity BYTEA,source_binding_lineage_root BYTEA,source_binding_lineage_version BIGINT,batch_digest BYTEA,batch_bytes BYTEA,row_count BIGINT) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT b.source_binding_identity,b.source_binding_lineage_root,b.source_binding_lineage_version,b.batch_digest,b.batch_bytes,b.row_count FROM market_data_private.pit_observation_batches_v1 b WHERE b.snapshot_identity=p_snapshot AND session_user='rd_owner' FOR SHARE OF b $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_pit_observation_rows_for_strategy_input_v1(p_snapshot BYTEA) RETURNS TABLE(ordinal BIGINT,symbolic_key TEXT,member_key TEXT,row_bytes BYTEA) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT r.ordinal,r.symbolic_key,r.member_key,r.row_bytes FROM market_data_private.pit_observation_rows_v1 r WHERE r.snapshot_identity=p_snapshot AND session_user='rd_owner' ORDER BY r.ordinal FOR SHARE OF r $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_universe_for_strategy_input_v1(p_selection BYTEA) RETURNS TABLE(request_identity BYTEA,request_meaning_digest BYTEA,selection_identity BYTEA,record_bytes BYTEA,receipt_identity BYTEA,receipt_bytes BYTEA,outbox_identity BYTEA,outbox_receipt_bytes BYTEA) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT r.request_identity,r.request_meaning_digest,r.selection_identity,r.record_bytes,c.receipt_identity,c.receipt_bytes,o.outbox_identity,o.receipt_bytes FROM market_data_private.universe_selection_records_v1 r JOIN market_data_private.universe_selection_receipts_v1 c ON c.request_identity=r.request_identity JOIN market_data_private.universe_selection_outbox_v1 o ON o.request_identity=r.request_identity WHERE r.selection_identity=p_selection AND session_user='rd_owner' FOR SHARE OF r,c,o $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_market_semantics_scope_for_strategy_input_v1(p_scope BYTEA) RETURNS TABLE(request_identity BYTEA,fact_identity BYTEA,fact_bytes BYTEA) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT r.request_identity,f.fact_identity,f.fact_bytes FROM market_data_private.market_semantics_receipts_v1 r JOIN market_data_private.market_semantics_facts_v1 f ON f.fact_identity=r.fact_identity WHERE f.compatibility_scope_identity=p_scope AND session_user='rd_owner' FOR SHARE OF r,f $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_market_semantics_readback_for_strategy_input_v1(p_request BYTEA) RETURNS TABLE(request_meaning_digest BYTEA,cut_identity BYTEA,cut_bytes BYTEA,receipt_identity BYTEA,receipt_bytes BYTEA,readback_identity BYTEA,readback_bytes BYTEA,append_sequence BIGINT,outbox_identity BYTEA,payload BYTEA,stored_fact_bytes BYTEA,store_generation_identity BYTEA,state_append_sequence BIGINT) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT c.request_meaning_digest,c.cut_identity,c.cut_bytes,r.receipt_identity,r.receipt_bytes,r.readback_identity,r.readback_bytes,r.append_sequence,o.outbox_identity,o.payload,f.fact_bytes,s.store_generation_identity,s.append_sequence FROM market_data_private.market_semantics_cuts_v1 c JOIN market_data_private.market_semantics_receipts_v1 r ON r.request_identity=c.request_identity JOIN market_data_private.market_semantics_outbox_v1 o ON o.request_identity=c.request_identity JOIN market_data_private.market_semantics_facts_v1 f ON f.fact_identity=r.fact_identity CROSS JOIN market_data_private.market_semantics_state_v1 s WHERE s.singleton AND c.request_identity=p_request AND session_user='rd_owner' FOR SHARE OF c,r,o,f,s $function$",
    "CREATE OR REPLACE FUNCTION market_data_rd_api.lock_pit_request_for_strategy_design_v1(p_design BYTEA) RETURNS TABLE(pit_request_identity BYTEA) LANGUAGE SQL VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $function$ SELECT d.pit_request_identity FROM market_data_private.strategy_input_binding_declarations_v1 d WHERE d.strategy_design_identity=p_design AND session_user='rd_owner' ORDER BY d.pit_request_identity,d.input_role_identity FOR SHARE OF d $function$",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_strategy_input_declarations_v1(BYTEA,BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_source_for_strategy_input_v1(BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_pit_observation_batch_for_strategy_input_v1(BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_pit_observation_rows_for_strategy_input_v1(BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_universe_for_strategy_input_v1(BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_market_semantics_scope_for_strategy_input_v1(BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_market_semantics_readback_for_strategy_input_v1(BYTEA) FROM PUBLIC",
    "REVOKE ALL ON FUNCTION market_data_rd_api.lock_pit_request_for_strategy_design_v1(BYTEA) FROM PUBLIC",
    "DO $grant$ BEGIN IF pg_catalog.to_regrole('rd_owner') IS NOT NULL THEN GRANT EXECUTE ON FUNCTION market_data_rd_api.lock_strategy_input_declarations_v1(BYTEA,BYTEA),market_data_rd_api.lock_source_for_strategy_input_v1(BYTEA),market_data_rd_api.lock_pit_observation_batch_for_strategy_input_v1(BYTEA),market_data_rd_api.lock_pit_observation_rows_for_strategy_input_v1(BYTEA),market_data_rd_api.lock_universe_for_strategy_input_v1(BYTEA),market_data_rd_api.lock_market_semantics_scope_for_strategy_input_v1(BYTEA),market_data_rd_api.lock_market_semantics_readback_for_strategy_input_v1(BYTEA),market_data_rd_api.lock_pit_request_for_strategy_design_v1(BYTEA) TO rd_owner; END IF; END $grant$",
];
